contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(address newOwner) public {
        address oldOwner = c.owner(); if (__ESBMC_reverted()) return;

        // The owner transfers ownership to newOwner (top-level call).
        c.transferOwnership(newOwner); if (__ESBMC_reverted()) return;

        // Call owned() from this contract (which is the owner at call time).
        bool revertedAfterOwner;
        c.owned(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            revertedAfterOwner = true;
        } else {
            revertedAfterOwner = false;
        }

        // General rule: after the owner transfers ownership, owner == newOwner,
        // and the new owner's owned() call succeeds.
        assert(c.owner() == newOwner && !revertedAfterOwner);
    }
}

